package com.justjava.humanresource.employeeexit.workflow.delegate; import com.justjava.humanresource.employeeexit.service.EmployeeExitService; import com.justjava.humanresource.employeeexit.service.EmployeeExitReadinessService; import lombok.RequiredArgsConstructor; import org.flowable.engine.delegate.*; import org.springframework.stereotype.Component;
@Component("evaluateExitReadinessDelegate") @RequiredArgsConstructor public class EvaluateExitReadinessDelegate implements JavaDelegate {private final EmployeeExitReadinessService readiness;private final EmployeeExitService service;public void execute(DelegateExecution e){Long id=((Number)e.getVariable("exitCaseId")).longValue();var result=readiness.validate(id);e.setVariable("exitReady",result.ready());e.setVariable("exitReadinessBlockers",result.summary());if(result.ready())service.evaluateReadiness(id);}}
